/*
 * COMPOSITION: A 7x6 graded backdrop (ink base + 2-stop gradient) sits at z=-2.5/-3,
 *   grounding a floating machined-metal rail (3.6x0.5x0.12) at z=0.15 with a soft
 *   contact-shadow plane beneath it. Five nav cells (surface chips + MSDF labels) are
 *   spaced 0.68 apart across the rail; the active "HOME" cell carries a red underline bar.
 * LIGHT RIG: node-local key spot (warm, 30deg key), fill point (cool bounce), and rim spot
 *   (cold rim on the trailing edge) scaled to the rail's ~1.8 unit bounding radius, riding
 *   atop the scene-provided ambient+key.
 * MATERIAL STRATEGY: rail = MeshPhysicalNodeMaterial (roughness 0.55, metalness 0.5,
 *   clearcoat 0.2, anisotropy 0.6, TSL vertical-gradient colorNode); chamfer highlight strip
 *   = bright metal sliver; cells/backdrop/shadow/underline = MeshBasicNodeMaterial /
 *   MeshStandardNodeMaterial with flat TSL color/emissive nodes — no raw shader strings.
 * MOTION: mount rise-in (y +0.4->0, 0.7s power3.out); hover recolors inactive labels
 *   a6adba->paper over 160ms; press dips a cell -0.03 in z with slight overshoot; activating
 *   a new entry slides the accent underline with a weighted 1.04 overshoot settle.
 * FOCAL ELEMENT: the accent-red underline bar beneath "HOME" — the single brightest,
 *   highest-saturation object in the frame; everything else (metal rail, paper text) reads
 *   below it in emphasis.
 */
import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

const COLORS = {
  background: '#0b0b10',
  surface: '#14141a',
  ink: '#16161d',
  paper: '#e8ecf2',
  accent: '#ff2a38',
  inactive: '#a6adba',
  gradientTop: '#1b1b23',
  gradientBottom: '#101015',
};

const NAV_ITEMS = [
  { text: 'HOME', active: true },
  { text: 'FEATURES', active: false },
  { text: 'COLLECTION', active: false },
  { text: 'PRICING', active: false },
  { text: 'JOURNAL', active: false },
];

const NAV_TARGETS = ['hub-home', 'hub-features', 'hub-collection', 'hub-pricing', 'hub-journal'];

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const disposables = [];
  const timelines = [];

  const root = new THREE.Group();
  root.name = 'nova-nav-dock';

  // ---- backdrop (color.background + color.gradient) ----
  const bgGeo = new THREE.PlaneGeometry(8, 7);
  const bgMat = new MeshBasicNodeMaterial();
  bgMat.colorNode = color(COLORS.ink); // color.ink — base stage tone behind gradient
  const bgPlane = new THREE.Mesh(bgGeo, bgMat);
  bgPlane.position.set(0, 0, -3);
  root.add(bgPlane);
  disposables.push(bgGeo, bgMat);

  const gradGeo = new THREE.PlaneGeometry(7, 6);
  const gradMat = new MeshBasicNodeMaterial();
  gradMat.colorNode = mix(color(COLORS.gradientTop), color(COLORS.gradientBottom), uv().y); // color.gradient
  const gradPlane = new THREE.Mesh(gradGeo, gradMat);
  gradPlane.position.set(0, 0, -2.5);
  root.add(gradPlane);
  disposables.push(gradGeo, gradMat);

  // faint background-color wash near rail so color.background is literally present
  const washGeo = new THREE.PlaneGeometry(5.2, 1.6);
  const washMat = new MeshBasicNodeMaterial();
  washMat.colorNode = color(COLORS.background); // color.background
  washMat.transparent = true;
  washMat.opacity = 0.55;
  const washPlane = new THREE.Mesh(washGeo, washMat);
  washPlane.position.set(0, 0, -0.3);
  root.add(washPlane);
  disposables.push(washGeo, washMat);

  // ---- contact shadow plane ----
  const shadowGeo = new THREE.PlaneGeometry(1.6 * 3.6, 1.6 * 0.5);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.colorNode = color(COLORS.background); // color.background reused for grounding shadow
  shadowMat.transparent = true;
  shadowMat.opacity = 0.35;
  const shadowPlane = new THREE.Mesh(shadowGeo, shadowMat);
  shadowPlane.position.set(0, -0.06, -0.02);
  root.add(shadowPlane);
  disposables.push(shadowGeo, shadowMat);

  // ---- machined rail (effects.spec) ----
  const railWidth = 3.6, railHeight = 0.5, railDepth = 0.12;
  const railGeo = new THREE.BoxGeometry(railWidth, railHeight, railDepth, 32, 4, 1);
  const railMat = new MeshPhysicalNodeMaterial();
  railMat.colorNode = mix(color(COLORS.gradientTop), color(COLORS.gradientBottom), uv().y); // vertical albedo ramp
  railMat.roughness = 0.55;
  railMat.metalness = 0.5;
  railMat.clearcoat = 0.2;
  railMat.clearcoatRoughness = 0.3;
  railMat.anisotropy = 0.6;
  railMat.anisotropyRotation = 0;
  const rail = new THREE.Mesh(railGeo, railMat);
  rail.position.set(0, 0, 0.15); // translateZ +0.15 above contact shadow
  root.add(rail);
  disposables.push(railGeo, railMat);

  // chamfered edge specular line
  const chamferGeo = new THREE.BoxGeometry(railWidth - 0.04, 0.02, railDepth + 0.01);
  const chamferMat = new MeshPhysicalNodeMaterial();
  chamferMat.colorNode = color('#c9ccd4');
  chamferMat.metalness = 1.0;
  chamferMat.roughness = 0.18;
  chamferMat.clearcoat = 0.25;
  const chamfer = new THREE.Mesh(chamferGeo, chamferMat);
  chamfer.position.set(0, railHeight / 2 - 0.02, 0.15);
  root.add(chamfer);
  disposables.push(chamferGeo, chamferMat);

  // ---- nav-local light rig (product-hero preset, scaled to rail radius ~1.8) ----
  const lightsGroup = new THREE.Group();
  const key = new THREE.SpotLight(0xfff2e0, 65 * 0.035, 0, 0.5, 0.55);
  key.position.set(2.2 * 0.55, 3.2 * 0.35, 2.4 * 0.4);
  key.target.position.set(0, 0.1, 0.15);
  lightsGroup.add(key, key.target);

  const fill = new THREE.PointLight(0xd8dde6, 4 * 0.12, 9, 2);
  fill.position.set(-2.8 * 0.5, 0.9 * 0.4, 2 * 0.4);
  lightsGroup.add(fill);

  const rim = new THREE.SpotLight(0xffffff, 48 * 0.02, 0, 0.6, 0.4);
  rim.position.set(-1.6 * 0.55, 2.6 * 0.3, -2.2 * 0.3);
  rim.target.position.set(0, 0.15, 0.15);
  rim.color.set(COLORS.accent).lerp(new THREE.Color(0xffffff), 0.5);
  lightsGroup.add(rim, rim.target);

  root.add(lightsGroup);

  // ---- entries ----
  const centers = [-1.36, -0.68, 0, 0.68, 1.36];
  const cellW = 0.6, cellH = 0.34, cellD = 0.02;
  const entryGroups = [];
  const cellMeshes = [];
  const textMeshes = [];
  let activeIndex = 0;
  let underlineTargetX = centers[0];

  const underlineGeo = new THREE.BoxGeometry(0.28, 0.025, 0.01);
  const underlineMat = new MeshStandardNodeMaterial();
  underlineMat.colorNode = color(COLORS.accent); // color.accent
  underlineMat.emissive = new THREE.Color(COLORS.accent);
  underlineMat.emissiveIntensity = 1.8;
  underlineMat.roughness = 0.4;
  underlineMat.metalness = 0.0;
  const underline = new THREE.Mesh(underlineGeo, underlineMat);
  underline.position.set(centers[0], -railHeight / 2 + 0.06 - 0.06, 0.22);
  root.add(underline);
  disposables.push(underlineGeo, underlineMat);

  NAV_ITEMS.forEach((item, i) => {
    const cx = centers[i];
    const entry = new THREE.Group();
    entry.position.set(cx, 0, 0.16);
    entry.userData.index = i;

    const cellGeo = new THREE.BoxGeometry(cellW, cellH, cellD);
    const cellMat = new MeshBasicNodeMaterial();
    cellMat.colorNode = color(COLORS.surface); // color.surface
    cellMat.transparent = true;
    cellMat.opacity = 0.9;
    const cell = new THREE.Mesh(cellGeo, cellMat);
    cell.position.set(0, 0, 0.03);
    entry.add(cell);
    disposables.push(cellGeo, cellMat);
    cellMeshes.push(cell);

    const label = ctx.fontAtlas.createText(item.text, {
      fontSize: 13,
      color: item.active ? COLORS.paper : COLORS.inactive,
      align: 'center',
      letterSpacingPx: 0.08 * 13,
    });
    label.position.set(0, 0, 0.05);
    // typography scale correction: 13px atlas -> scene units
    label.scale.setScalar(0.02);
    entry.add(label);
    textMeshes.push(label);

    root.add(entry);
    entryGroups.push(entry);
  });

  // mount motion: rise-in
  root.position.y += 0.4;
  const riseTl = gsap.timeline();
  riseTl.to(root.position, {
    y: root.position.y - 0.4,
    duration: 0.7,
    ease: 'power3.out',
  });
  timelines.push(riseTl);

  // ---- interaction handlers ----
  function setEntryColor(idx, hex, duration = 0.16) {
    const mat = textMeshes[idx].material;
    if (!mat || !mat.color) return;
    const target = new THREE.Color(hex);
    const tl = gsap.to(mat.color, {
      r: target.r,
      g: target.g,
      b: target.b,
      duration,
      ease: 'power2.out',
    });
    timelines.push(tl);
  }

  function onHoverStart(idx) {
    if (idx === activeIndex) return;
    setEntryColor(idx, COLORS.paper, 0.16);
  }

  function onHoverEnd(idx) {
    if (idx === activeIndex) return;
    setEntryColor(idx, COLORS.inactive, 0.16);
  }

  function onPressStart(idx) {
    const entry = entryGroups[idx];
    const tl = gsap.timeline();
    tl.to(entry.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
    tl.to(entry.position, { z: entry.position.z - 0.03, duration: 0.12, ease: 'back.out(2)' }, 0);
    timelines.push(tl);
  }

  function onPressEnd(idx) {
    const entry = entryGroups[idx];
    const tl = gsap.timeline();
    tl.to(entry.scale, { x: 1, y: 1, z: 1, duration: 0.12, ease: 'power2.out' });
    tl.to(entry.position, { z: 0.16, duration: 0.12, ease: 'power2.out' }, 0);
    timelines.push(tl);
  }

  function onActivate(idx) {
    if (idx === activeIndex) return;
    setEntryColor(activeIndex, COLORS.inactive, 0.16);
    activeIndex = idx;
    setEntryColor(activeIndex, COLORS.paper, 0.16);
    underlineTargetX = centers[idx];
    const tl = gsap.timeline();
    tl.to(underline.position, {
      x: underlineTargetX * 1.04,
      duration: 0.18,
      ease: 'power2.out',
    });
    tl.to(underline.position, {
      x: underlineTargetX,
      duration: 0.08,
      ease: 'power4.out',
    });
    timelines.push(tl);
    ctx.emit('navigate', { to: NAV_TARGETS[idx] });
  }

  root.userData.handlers = {
    onHoverStart,
    onHoverEnd,
    onPressStart,
    onPressEnd,
    onActivate,
    onClick: onActivate,
  };

  root.userData.cleanup = function cleanup() {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    disposables.forEach((res) => {
      if (res && typeof res.dispose === 'function') res.dispose();
    });
    textMeshes.forEach((t) => {
      if (t.geometry && typeof t.geometry.dispose === 'function') t.geometry.dispose();
      if (t.material) {
        if (t.material.map && typeof t.material.map.dispose === 'function') t.material.map.dispose();
        if (typeof t.material.dispose === 'function') t.material.dispose();
      }
    });
    lightsGroup.children.forEach((l) => {
      if (l.dispose) l.dispose();
    });
    root.clear();
  };

  return root;
}

/* @spec-manifest
{"elements":[
  {"id":"text.nav-active.0","where":"NAV_ITEMS/entryGroups loop","how":"createText('HOME') with paper color, marked active"},
  {"id":"text.nav-item.1","where":"NAV_ITEMS/entryGroups loop","how":"createText('FEATURES') inactive label"},
  {"id":"text.nav-item.2","where":"NAV_ITEMS/entryGroups loop","how":"createText('COLLECTION') inactive label"},
  {"id":"text.nav-item.3","where":"NAV_ITEMS/entryGroups loop","how":"createText('PRICING') inactive label"},
  {"id":"text.nav-item.4","where":"NAV_ITEMS/entryGroups loop","how":"createText('JOURNAL') inactive label"},
  {"id":"color.background","where":"washPlane/shadowPlane materials","how":"MeshBasicNodeMaterial colorNode(#0b0b10) wash + shadow"},
  {"id":"color.surface","where":"cellMat in entries loop","how":"MeshBasicNodeMaterial colorNode(#14141a) nav chip"},
  {"id":"color.ink","where":"bgMat outer backdrop plane","how":"MeshBasicNodeMaterial colorNode(#16161d) base stage"},
  {"id":"color.paper","where":"setEntryColor + initial label color","how":"active label color #e8ecf2, hover target"},
  {"id":"color.accent","where":"underlineMat","how":"MeshStandardNodeMaterial colorNode+emissive(#ff2a38)"},
  {"id":"color.gradient","where":"gradMat and railMat colorNode","how":"TSL mix(#1b1b23,#101015) vertical uv().y gradient"},
  {"id":"effects.spec","where":"rail/chamfer/shadow/underline/entries block","how":"3.6x0.5 rail PBR anisotropy+clearcoat, chamfer strip, shadow, spacing, motion handlers"}
]}
*/
